import{_ as t,a}from"./chunks/catalog-graph.CJH_PNkf.js";import{_ as s,o as i,c as n,O as r}from"./chunks/framework.4XV3vnnU.js";const m=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/getting-started.md","filePath":"documentation/getting-started.md","lastUpdated":1793117788000}'),l={name:"documentation/getting-started.md"};function o(h,e,d,p,c,k){return i(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>This guide brings up a complete Naira environment on your machine: the catalog with its plugins, the portal, and sample systems for the plugins to read from (Keycloak, LiteLLM, MLflow, llama.cpp and a mock MCP server). Everything runs in a local <a href="https://kind.sigs.k8s.io/" target="_blank" rel="noreferrer">kind</a> cluster driven by <a href="https://tilt.dev/" target="_blank" rel="noreferrer">Tilt</a>.</p><p>For installing Naira into an existing cluster, see <a href="/pr-preview/pr-12/documentation/deployment">Deployment</a>.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><a href="https://www.docker.com/" target="_blank" rel="noreferrer">Docker</a> (Docker Desktop or Docker Engine)</li><li><a href="https://mise.jdx.dev/" target="_blank" rel="noreferrer">mise</a>, which installs every other tool in the pinned version</li></ul><p>Clone the repository and let mise install the tools listed in <code>mise.toml</code> (kind, kubectl, helm, tilt, task, go and the linters):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/naira-project/naira.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> naira</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>If you prefer to install tools by hand, <code>mise.toml</code> lists the exact versions.</p><h2 id="create-the-cluster-and-deploy" tabindex="-1">Create the cluster and deploy <a class="header-anchor" href="#create-the-cluster-and-deploy" aria-label="Permalink to &quot;Create the cluster and deploy&quot;">​</a></h2><p>Create the kind cluster once. This also selects its kube context:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kind</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cluster</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> naira-idp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kindest/node:v1.36.1</span></span></code></pre></div><p>Then deploy the platform:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tilt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span></span></code></pre></div><p>Tilt builds the container images, installs the published <a href="https://github.com/naira-project/test-dependencies" target="_blank" rel="noreferrer">test-dependencies</a> chart into the <code>naira-deps</code> namespace and the Naira chart into <code>idp-system</code>, and port-forwards the services. It refuses to run if the kube context is not <code>kind-naira-idp</code>, so it cannot touch another cluster by accident.</p><p>Open the Tilt UI (it prints the address, usually <code>http://localhost:10350</code>) and wait until the resources are green. The first run takes a while because it builds all images and pulls the dependencies.</p><h2 id="log-in-and-explore" tabindex="-1">Log in and explore <a class="header-anchor" href="#log-in-and-explore" aria-label="Permalink to &quot;Log in and explore&quot;">​</a></h2><p>Open the portal at <code>http://localhost:3000</code> and log in to Keycloak with the development credentials:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>user</td><td><code>testuser</code></td></tr><tr><td>password</td><td><code>testpass</code></td></tr></tbody></table><p>The catalog is empty until plugins have run. Go to <strong>Plugins</strong> and click <strong>Run All Plugins</strong>. Plugins that have no target in the local environment show as failed, which is expected. Then open one of the catalogs, for example the <strong>Model Catalog</strong>, or the <strong>Software Catalog</strong> for the deployments and services running in the cluster.</p><p><img src="`+t+'" alt="Catalog explorer listing models with their properties"></p><p>Click an entry to open its detail page. The <strong>Graph</strong> tab shows the entry and its relationships, the <strong>Properties</strong> tab lists what each plugin reported about it.</p><p><img src="'+a+`" alt="Graph view of a catalog entry and its neighbours"></p><p><a href="/pr-preview/pr-12/documentation/portal">The Portal</a> describes every page in more detail.</p><h2 id="what-is-running-where" tabindex="-1">What is running where <a class="header-anchor" href="#what-is-running-where" aria-label="Permalink to &quot;What is running where&quot;">​</a></h2><p>Tilt forwards the services below to localhost. Dependencies are only forwarded when enabled in the test-dependencies chart.</p><table tabindex="0"><thead><tr><th>Service</th><th>Address</th></tr></thead><tbody><tr><td>Portal (login here)</td><td><code>http://localhost:3000</code></td></tr><tr><td>UI (standalone, without the portal shell)</td><td><code>http://localhost:3001</code></td></tr><tr><td>Catalog API</td><td><code>http://localhost:8090</code></td></tr><tr><td>Keycloak</td><td><code>http://localhost:8080</code></td></tr><tr><td>LiteLLM</td><td><code>http://localhost:4000</code></td></tr><tr><td>MLflow</td><td><code>http://localhost:5001</code></td></tr><tr><td>MCP mock server</td><td><code>http://localhost:8081</code></td></tr></tbody></table><p>MLflow is forwarded to port 5001 because macOS reserves port 5000 for AirPlay.</p><p>To call the API directly, fetch a token from Keycloak and pass it as a bearer token. See <a href="/pr-preview/pr-12/documentation/api">Catalog API</a>.</p><h2 id="change-the-environment" tabindex="-1">Change the environment <a class="header-anchor" href="#change-the-environment" aria-label="Permalink to &quot;Change the environment&quot;">​</a></h2><p>The components of the dependency chart are selected through <code>tags</code> in its values. To change them, or to work on the chart itself, point Tilt at a local checkout:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tilt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --deps-repo=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-dependencies</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkou</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Naira&#39;s own development values, including the enabled plugins and the sample Tech Radar, are in <code>deploy/charts/naira/values-dev.yaml</code>. Tilt watches the chart and re-applies changes.</p><h2 id="tear-down" tabindex="-1">Tear down <a class="header-anchor" href="#tear-down" aria-label="Permalink to &quot;Tear down&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tilt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                               # removes everything Tilt deployed</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kind</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cluster</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> naira-idp</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # removes the cluster</span></span></code></pre></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/pr-preview/pr-12/documentation/concepts">Concepts</a> explains nodes, relations, plugins and snapshots.</li><li><a href="/pr-preview/pr-12/documentation/plugins">Plugins</a> lists what each plugin reads and emits.</li><li><a href="/pr-preview/pr-12/documentation/contribute">Contribute</a> covers the developer tasks for tests, linting and chart checks.</li></ul>`,36)])])}const b=s(l,[["render",o]]);export{m as __pageData,b as default};
